import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.C7GIOALF.js";const f=JSON.parse('{"title":"BANG! Magic","description":"","frontmatter":{},"headers":[],"relativePath":"formats/bang-like/variants/bang-magic.md","filePath":"formats/bang-like/variants/bang-magic.md","lastUpdated":null}'),n={name:"formats/bang-like/variants/bang-magic.md"};function o(s,e,l,d,h,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="bang-magic" tabindex="-1">BANG! Magic <a class="header-anchor" href="#bang-magic" aria-label="Permalink to &quot;BANG! Magic&quot;">​</a></h1><p><a href="./../">BANG-like versions</a> · <strong>Rules: Saporling&#39;s Commander variant</strong></p><h2 id="players-and-materials" tabindex="-1">Players and materials <a class="header-anchor" href="#players-and-materials" aria-label="Permalink to &quot;Players and materials&quot;">​</a></h2><p>This version is intended for five to seven or more players using Commander decks. Prepare one hidden role card per player. Tokens or slips of paper are sufficient.</p><p>Use exactly one Sheriff, exactly one Renegade, at least one Deputy, and at least two Outlaws. At five players this means 1 Sheriff, 1 Deputy, 2 Outlaws, and 1 Renegade. The source does not assign a fixed distribution for larger groups; agree how the extra Deputy/Outlaw slots are filled before dealing.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Choose Commander decks using ordinary Commander construction and legality.</li><li>Agree the role distribution and whether the Sheriff receives a house bonus.</li><li>Shuffle the role cards and deal one secretly to each player.</li><li>Each player looks only at their own role. The Sheriff turns their role face up; the other roles remain hidden.</li><li>Start at the usual Commander life total of 40, modified by the chosen Sheriff bonus.</li><li>Draw seven cards, take normal multiplayer mulligans, and start with the Sheriff&#39;s turn.</li></ol><p>The original post describes <strong>+20 starting life</strong> as a usual house bonus, which gives the Sheriff 60 life. It is an optional choice, not a mandatory bonus specified for every game.</p><h2 id="turns-and-roles" tabindex="-1">Turns and roles <a class="header-anchor" href="#turns-and-roles" aria-label="Permalink to &quot;Turns and roles&quot;">​</a></h2><p>Play normal individual Commander turns. Commander tax and commander damage still apply. Hidden allegiances do not by themselves give shared life totals, shared turns, or permission to block for another player.</p><table tabindex="0"><thead><tr><th>Role</th><th>Objective</th></tr></thead><tbody><tr><td>Sheriff</td><td>Survive while all Outlaws and the Renegade are eliminated.</td></tr><tr><td>Deputy</td><td>Help the Sheriff eliminate all Outlaws and the Renegade.</td></tr><tr><td>Outlaw</td><td>Eliminate the Sheriff.</td></tr><tr><td>Renegade</td><td>Be the only surviving player.</td></tr></tbody></table><p>The Renegade must arrange a final confrontation with the Sheriff. Merely killing the Sheriff while other players remain does not give the Renegade a win.</p><h2 id="revealing-roles" tabindex="-1">Revealing roles <a class="header-anchor" href="#revealing-roles" aria-label="Permalink to &quot;Revealing roles&quot;">​</a></h2><p>Keep your role card hidden until you die, except for the public Sheriff. Reveal it when eliminated. Politics and bluffing are part of play; knowing what someone claims does not change the role they actually received.</p><p>The source does not impose the separate table-talk restrictions from Kingdom / BANG EDH.</p><h2 id="ending-the-game" tabindex="-1">Ending the game <a class="header-anchor" href="#ending-the-game" aria-label="Permalink to &quot;Ending the game&quot;">​</a></h2><ul><li>If the Sheriff survives and all Outlaws and the Renegade have been eliminated, the Sheriff and Deputies achieve their objective.</li><li>If the Sheriff dies before the Renegade can be the sole survivor, the game ends with an Outlaw win.</li><li>The Renegade wins only as the last living player. The source&#39;s corrected description specifically calls for a Sheriff-versus-Renegade finish.</li></ul><p>Apply ordinary Magic loss conditions to determine who has been eliminated. The short source does not resolve simultaneous mass-elimination ties or every alternate-win-card interaction; agree those cases before using such cards rather than importing another hidden-role version&#39;s answer.</p><h2 id="optional-rules-and-source-boundaries" tabindex="-1">Optional rules and source boundaries <a class="header-anchor" href="#optional-rules-and-source-boundaries" aria-label="Permalink to &quot;Optional rules and source boundaries&quot;">​</a></h2><p>The Sheriff bonus is the original post&#39;s house-rule option. Comments discuss rewards for killing Outlaws and penalties for killing a Deputy, but those additions disagree across commenters and are not part of this posted ruleset. The separately documented <a href="./kingdom-bang-edh.html">Kingdom / BANG EDH version</a> defines its own rewards and penalties.</p><p>Source: <a href="https://www.reddit.com/r/magicTCG/comments/1w81fm/bang_magic/" target="_blank" rel="noreferrer">Saporling&#39;s BANG! Magic post and author-confirmed Renegade correction</a>. <a href="./../sources/bang-magic-reddit.html">Archived notes</a>.</p>',21)])])}const m=a(n,[["render",o]]);export{f as __pageData,m as default};
